def test_window_is_half_open():
    reqs = [(0, "a"), (1, "a"), (2, "a"), (10, "a"), (11, "a")]
    assert rate_limit(reqs, 2, 100, 10) == [True, True, False, True, True]

def test_rejected_requests_do_not_count():
    reqs = [(0, "a"), (3, "a"), (5, "a")]
    assert rate_limit(reqs, 1, 100, 5) == [True, False, True]

def test_clients_are_independent():
    reqs = [(0, "a"), (0, "b"), (1, "a"), (1, "b"), (2, "c")]
    assert rate_limit(reqs, 1, 100, 10) == [True, True, False, False, True]

def test_global_limit_rejection_does_not_start_cooldown():
    reqs = [(0, "a"), (1, "b"), (2, "c"), (10, "c"), (11, "c")]
    assert rate_limit(reqs, 5, 2, 10, cooldown=20) == [True, True, False, True, True]

def test_cooldown_not_extended_by_cooldown_rejections():
    reqs = [(0, "a"), (1, "a"), (4, "a"), (5, "a")]
    assert rate_limit(reqs, 1, 100, 3, cooldown=4) == [True, False, False, True]

def test_cooldown_restarts_after_new_limit_rejection():
    reqs = [(0, "a"), (2, "a"), (7, "a"), (9, "a"), (12, "a")]
    assert rate_limit(reqs, 1, 100, 10, cooldown=5) == [True, False, False, False, True]

def test_failing_both_checks_starts_cooldown():
    reqs = [(0, "a"), (1, "a"), (3, "a")]
    assert rate_limit(reqs, 1, 1, 2, cooldown=5) == [True, False, False]

def test_unsorted_input_processed_by_timestamp():
    reqs = [(9, "a"), (0, "a"), (1, "a")]
    assert rate_limit(reqs, 1, 100, 10, cooldown=5) == [False, True, False]

def test_ties_broken_by_input_position():
    reqs = [(5, "b"), (5, "a"), (0, "c"), (20, "a")]
    assert rate_limit(reqs, 1, 1, 3) == [True, False, True, True]

