def rate_limit(requests, limit, global_limit, window, cooldown=0):
    order = sorted(range(len(requests)), key=lambda i: requests[i][0])
    result = [False] * len(requests)
    accepted = {}
    accepted_all = []
    blocked_until = {}
    for i in order:
        t, client = requests[i]
        if client in blocked_until and t < blocked_until[client]:
            continue
        lo = t - window
        per_client = sum(1 for s in accepted.get(client, []) if lo < s <= t)
        overall = sum(1 for s in accepted_all if lo < s <= t)
        if per_client >= limit:
            blocked_until[client] = t + cooldown
            continue
        if overall >= global_limit:
            continue
        result[i] = True
        accepted.setdefault(client, []).append(t)
        accepted_all.append(t)
    return result

