from collections import deque

def cost_of_sales(events, method="fifo"):
    stock = deque()
    sold = []
    out = []
    for ev in events:
        kind = ev[0]
        if kind == "buy":
            stock.extend([ev[2]] * ev[1])
        elif kind == "sell":
            qty = ev[1]
            if qty > len(stock):
                raise ValueError("not enough stock")
            total = 0
            for _ in range(qty):
                unit = stock.popleft() if method == "fifo" else stock.pop()
                sold.append(unit)
                total += unit
            out.append(total)
        elif kind == "return":
            qty = ev[1]
            if qty > len(sold):
                raise ValueError("returning more than was sold")
            back = sold[len(sold) - qty:]
            del sold[len(sold) - qty:]
            if method == "fifo":
                stock.extendleft(reversed(back))
            else:
                stock.extend(reversed(back))
            out.append(-sum(back))
    return out

