    assert sessionize(hits, 10, 100) == {"u": [(0, 15), (26, 30)]}

def test_users_are_independent():
    hits = [(0, "a"), (1, "b"), (3, "a"), (20, "b"), (22, "b"), (25, "a"), (26, "a")]
    assert sessionize(hits, 10, 100) == {"a": [(0, 3), (25, 26)], "b": [(20, 22)]}

def test_max_length_splits_session():
    hits = [(0, "u"), (8, "u"), (16, "u"), (24, "u"), (30, "u")]
    assert sessionize(hits, 10, 20) == {"u": [(0, 16), (24, 30)]}

def test_max_length_boundary_is_allowed():
    hits = [(0, "u"), (10, "u"), (20, "u"), (30, "u"), (35, "u")]
    assert sessionize(hits, 10, 20) == {"u": [(0, 20), (30, 35)]}

