def sessionize(hits, timeout, max_length):
    times = {}
    for t, user in set(hits):
        times.setdefault(user, []).append(t)
    result = {}
    for user, ts in times.items():
        ts.sort()
        sessions = []
        for t in ts:
            if sessions:
                start, last, count = sessions[-1]
                if t - last <= timeout and t - start <= max_length:
                    sessions[-1] = (start, t, count + 1)
                    continue
            sessions.append((t, t, 1))
        kept = [(s, e) for s, e, c in sessions if c > 1]
        if kept:
            result[user] = kept
    return result

