def run_ledger(events):
    balances = {}
    done = {}
    reversed_ids = set()
    for ev in events:
        kind = ev[0]
        if kind == "deposit":
            _, tid, acct, amt = ev
            balances.setdefault(acct, 0)
            balances[acct] += amt
            done[tid] = {acct: amt}
        elif kind == "withdraw":
            _, tid, acct, amt = ev
            balances.setdefault(acct, 0)
            if amt <= balances[acct]:
                balances[acct] -= amt
                done[tid] = {acct: -amt}
        elif kind == "transfer":
            _, tid, src, dst, amt = ev
            balances.setdefault(src, 0)
            balances.setdefault(dst, 0)
            if amt <= balances[src]:
                balances[src] -= amt
                balances[dst] += amt
                effect = {}
                effect[src] = effect.get(src, 0) - amt
                effect[dst] = effect.get(dst, 0) + amt
                done[tid] = effect
        elif kind == "reverse":
            tid = ev[1]
            if tid not in done or tid in reversed_ids:
                continue
            undo = {a: -x for a, x in done[tid].items()}
            if any(balances[a] + x < 0 for a, x in undo.items()):
                continue
            for a, x in undo.items():
                balances[a] += x
            reversed_ids.add(tid)
    return balances

