def parking_fees(events, rate, grace, daily_cap, capacity):
    def fee(d):
        if d <= grace:
            return 0
        days, rest = divmod(d, 1440)
        hours = -(-rest // 60)
        return days * daily_cap + min(hours * rate, daily_cap)

    order = sorted(range(len(events)), key=lambda i: (events[i][0], 0 if events[i][1] == "out" else 1))
    inside = {}
    fees = {}
    for i in order:
        minute, kind, plate = events[i]
        if kind == "in":
            if plate in inside or len(inside) >= capacity:
                continue
            inside[plate] = minute
        else:
            if plate not in inside:
                continue
            fees[plate] = fees.get(plate, 0) + fee(minute - inside.pop(plate))
    return fees

