def token_bucket(requests, capacity, refill_every, reserve):
    tokens = capacity
    last_tick = 0
    out = []
    for t, cost, priority in requests:
        tick = t // refill_every
        if tick > last_tick:
            tokens = min(capacity, tokens + (tick - last_tick))
            last_tick = tick
        needed = cost + (reserve if priority == "low" else 0)
        if tokens >= needed:
            tokens -= cost
            out.append(True)
        else:
            out.append(False)
    return out

