def match_orders(events):
    book = {"buy": [], "sell": []}
    seq = 0
    trades = []
    for ev in events:
        if ev[0] == "cancel":
            for side in book:
                book[side] = [o for o in book[side] if o[2] != ev[1]]
            continue
        if ev[0] == "limit":
            _, oid, side, price, qty, trader = ev
        else:
            _, oid, side, qty, trader = ev
            price = None
        opp = "sell" if side == "buy" else "buy"
        while qty > 0:
            if side == "buy":
                cands = [o for o in book[opp] if price is None or o[0] <= price]
                best = min(cands, key=lambda o: (o[0], o[1]), default=None)
            else:
                cands = [o for o in book[opp] if price is None or o[0] >= price]
                best = min(cands, key=lambda o: (-o[0], o[1]), default=None)
            if best is None:
                break
            if best[4] == trader:
                book[opp].remove(best)
                continue
            q = min(qty, best[3])
            if side == "buy":
                trades.append((oid, best[2], best[0], q))
            else:
                trades.append((best[2], oid, best[0], q))
            qty -= q
            best[3] -= q
            if best[3] == 0:
                book[opp].remove(best)
        if qty > 0 and price is not None:
            book[side].append([price, seq, oid, qty, trader])
            seq += 1
    return trades

