from collections import deque

def round_robin(jobs, quantum, switch):
    pending = deque(sorted(range(len(jobs)), key=lambda i: jobs[i][1]))
    remaining = {job_id: burst for job_id, _, burst in jobs}
    queue = deque()
    done = {}
    t = 0
    last = None

    def admit(upto):
        while pending and jobs[pending[0]][1] <= upto:
            queue.append(jobs[pending.popleft()][0])

    while pending or queue:
        admit(t)
        if not queue:
            t = jobs[pending[0]][1]
            last = None
            admit(t)
        job = queue.popleft()
        if last is not None and job != last:
            t += switch
        run = min(quantum, remaining[job])
        t += run
        remaining[job] -= run
        admit(t)
        if remaining[job] == 0:
            done[job] = t
        else:
            queue.append(job)
        last = job
    return done

