def library_fees(events, loan_days, fee_per_day, max_fee, block_above):
    loans = {}
    queues = {}
    fees = {}

    def blocked(member):
        return fees.get(member, 0) > block_above

    def lend(book, member, day):
        loans[book] = (member, day + loan_days)
        fees.setdefault(member, 0)

    for day, action, member, book in events:
        if action == "checkout":
            if book not in loans and not blocked(member):
                lend(book, member, day)
        elif action == "return":
            if book not in loans or loans[book][0] != member:
                continue
            _, due = loans.pop(book)
            if day > due:
                fees[member] += min((day - due) * fee_per_day, max_fee)
            queue = queues.get(book, [])
            while queue:
                nxt = queue.pop(0)
                if not blocked(nxt):
                    lend(book, nxt, day)
                    break
        elif action == "hold":
            if book in loans and loans[book][0] != member and member not in queues.get(book, []):
