def book_seats(events, n_seats, row_len, hold_ttl):
    sold = {}
    holds = []
    for ev in events:
        t, kind, user = ev[0], ev[1], ev[2]
        holds = [h for h in holds if h[2] > t]
        if kind == "hold":
            k = ev[3]
            busy = set(sold) | {s for h in holds for s in h[1]}
            for start in range(1, n_seats - k + 2):
                if (start - 1) // row_len != (start + k - 2) // row_len:
                    continue
                block = list(range(start, start + k))
                if all(s not in busy for s in block):
                    holds.append([user, block, t + hold_ttl])
                    break
        elif kind == "confirm":
            for h in holds:
                if h[0] == user:
                    for s in h[1]:
                        sold[s] = user
            holds = [h for h in holds if h[0] != user]
        elif kind == "release":
            holds = [h for h in holds if h[0] != user]
    result = {}
    for seat, user in sold.items():
        result.setdefault(user, []).append(seat)
    return {user: sorted(seats) for user, seats in result.items()}

