def circuit_breaker(calls, threshold, cooldown, probes, window):
    state = "closed"
    open_time = None
    failures = []
    streak = 0
    out = []
    for t, ok in calls:
        if state == "open":
            if t >= open_time + cooldown:
                state = "half"
                streak = 0
            else:
                out.append("rejected")
                continue
        out.append("ok" if ok else "fail")
        if state == "half":
            if ok:
                streak += 1
                if streak >= probes:
                    state = "closed"
                    failures = []
            else:
                state = "open"
                open_time = t
        else:
            if not ok:
                failures.append(t)
                if sum(1 for f in failures if f > t - window) >= threshold:
                    state = "open"
                    open_time = t
    return out

