def test_proxy_bidding():
    bids = [(1, "a", 50), (2, "b", 30), (3, "c", 60)]
    assert run_auction(bids, 10, 1, 1000, 0, 0) == ("c", 51)

def test_new_leader_price_capped_by_own_max():
    assert run_auction([(1, "a", 20), (2, "b", 21)], 10, 5, 1000, 0, 0) == ("b", 21)

def test_tie_keeps_existing_leader():
    assert run_auction([(1, "a", 40), (2, "b", 40)], 10, 5, 1000, 0, 0) == ("a", 40)

def test_invalid_bids_ignored():
    bids = [(1, "a", 5), (2, "b", 12), (3, "c", 16), (4, "a", 17)]
    assert run_auction(bids, 10, 5, 1000, 0, 0) == ("c", 16)
    assert run_auction([(1, "a", 5)], 10, 5, 1000, 0, 0) == (None, None)

def test_leader_raise_keeps_price():
    assert run_auction([(1, "a", 20), (2, "a", 50)], 10, 1, 1000, 0, 0) == ("a", 10)
    assert run_auction([(1, "a", 20), (2, "a", 50), (3, "b", 30)], 10, 1, 1000, 0, 0) == ("a", 31)

def test_soft_close_extends_from_bid_time():
    bids = [(50, "a", 20), (95, "b", 30), (104, "a", 40), (115, "b", 45), (120, "c", 100)]
    assert run_auction(bids, 10, 1, 100, 10, 0) == ("a", 31)

def test_bid_exactly_at_end_counts():
    assert run_auction([(10, "a", 20), (100, "b", 30)], 10, 1, 100, 0, 0) == ("b", 21)

def test_only_valid_non_leader_bids_extend():
    assert run_auction([(10, "a", 20), (95, "a", 50), (104, "b", 60)], 10, 1, 100, 10, 0) == ("a", 10)
    assert run_auction([(10, "a", 50), (95, "b", 10), (104, "c", 60)], 10, 5, 100, 10, 0) == ("a", 10)
    assert run_auction([(95, "a", 20), (104, "b", 30)], 10, 1, 100, 10, 0) == ("b", 21)

def test_reserve():
    bids = [(1, "a", 50), (2, "b", 30)]
    assert run_auction(bids, 10, 1, 1000, 0, 40) == ("a", 40)
    assert run_auction(bids, 10, 1, 1000, 0, 60) == (None, None)
    assert run_auction(bids, 10, 1, 1000, 0, 50) == ("a", 50)
    assert run_auction(bids, 10, 1, 1000, 0, 20) == ("a", 31)

