def run_auction(bids, start_price, increment, end_time, extension, reserve):
    leader = None
    leader_max = None
    price = None
    end = end_time
    for t, bidder, amount in bids:
        if t > end:
            continue
        if leader is None:
            if amount >= start_price:
                leader, leader_max, price = bidder, amount, start_price
                if t > end - extension:
                    end = t + extension
            continue
        if bidder == leader:
            if amount > leader_max:
                leader_max = amount
            continue
        if amount < price + increment:
            continue
        if amount > leader_max:
            price = min(amount, leader_max + increment)
            leader, leader_max = bidder, amount
        else:
            price = min(leader_max, amount + increment)
        if t > end - extension:
            end = t + extension
    if leader is None or leader_max < reserve:
        return (None, None)
    return (leader, max(price, reserve))

